import hashlib, re, pathlib

files = {
  ".env": ["APP_ENV","INCIDENT_ID","PAYMENTS_API_BASE","STRIPE_SECRET_KEY","DATABASE_URL"],
  "config/payment-runtime.env": ["PAYMENT_PROCESSOR_ACCOUNT","PAYMENT_WEBHOOK_SECRET","PAYMENT_WEBHOOK_URL"],
  "config/ir-vault.env": ["IR_VAULT_TOKEN","AWS_ACCESS_KEY_ID","AWS_SECRET_ACCESS_KEY"],
}
SECRET = {"STRIPE_SECRET_KEY","PAYMENT_WEBHOOK_SECRET","DATABASE_URL","IR_VAULT_TOKEN","AWS_SECRET_ACCESS_KEY","AWS_ACCESS_KEY_ID"}

def vals(p):
    d={}
    for line in pathlib.Path(p).read_text().splitlines():
        m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*)=(.*)$', line)
        if m: d[m.group(1)]=m.group(2).strip().strip('"').strip("'")
    return d

def cls(name,v):
    if v.startswith("sk_live") or v.startswith("rk_live"): return "live_key"
    if v.startswith("sk_test"): return "test_key"
    if name=="PAYMENT_WEBHOOK_SECRET": return "webhook_secret_present"
    if name=="DATABASE_URL": return "database_url_present"
    if name=="IR_VAULT_TOKEN": return "vault_token_present"
    if name.startswith("AWS_SECRET"): return "cloud_secret_present"
    if name.startswith("AWS_ACCESS"): return "cloud_access_key_present"
    return "non_secret"

out=["INCIDENT_ID=SEC-7421","# Redacted correlation summary (policy: value classes + version fingerprints only)"]
for f,names in files.items():
    d=vals(f)
    for n in names:
        if n not in d: 
            out.append(f"{n}=ABSENT"); continue
        v=d[n]
        if n in SECRET:
            fp=hashlib.sha256(v.encode()).hexdigest()[:12]
            out.append(f"{n}=present class={cls(n,v)} version_fp=sha256:{fp}")
        else:
            out.append(f"{n}={v}")
pathlib.Path("/tmp/sec7421-redacted-correlation.txt").write_text("\n".join(out)+"\n")
print("\n".join(out))
PY
